    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    canvas = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    # Transpose the canvas. The isolated exterior markers specify color
    # substitutions: map each internal color to the marker-color list
    # in the order encountered across the canvas.
    outside = {}
    for r in range(h):
        for c in range(w):
            if not (r0 <= r <= r1 and c0 <= c <= c1) and grid[r][c] != 0:
                outside.setdefault(grid[r][c], []).append((r, c))
    marker_colors = list(outside)
    internal = sorted({v for row in canvas for v in row if v not in (0, 1)})
    mapping = {}
    if len(marker_colors) == len(internal):
        mapping = dict(zip(internal, marker_colors))
    canvas = [[mapping.get(v, v) for v in row] for row in canvas]
    return [list(row) for row in zip(*canvas)]
