    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    # Exterior color markers determine pairwise color substitutions in the
    # framed picture; markers are ordered by their positions in the input.
    ext = []
    for r in range(h):
        for c in range(w):
            if not (r0 <= r <= r1 and c0 <= c <= c1) and grid[r][c] != 0:
                ext.append((r, c, grid[r][c]))
    ext.sort()
    colors = []
    for _, _, color in ext:
        if color not in colors:
            colors.append(color)
    if len(colors) >= 2:
        a, b = colors[0], colors[1]
        out = [[b if v == a else a if v == b else v for v in row] for row in out]
    return out
